// Push gate for the meal-planning agent. Decides whether a push may go now.
// It never sends anything. History is kept in memory, one gate per createPushGate() call.
//
// Choices (see the notes in the answer):
// - "Per day" is the user's own calendar day in their device time zone, not a rolling 24 hours.
// - "Night" is the user's quiet window in their device time zone. Start is included, end is excluded.
// - A window whose start is later than its end wraps past midnight. Equal start and end means no window.
// - Anything the gate cannot read (bad zone, bad HH:MM, bad cap, bad time) is held, never guessed.
// - Only allowed pushes count toward the daily cap. A refused attempt spends nothing.

const HH_MM = /^([01]\d|2[0-3]):([0-5]\d)$/;
const KEEP_DAYS = 4;

function refuse(reason) {
  return { allowed: false, reason };
}

// Local calendar date (YYYY-MM-DD) and minute-of-day in the given IANA zone.
// Throws RangeError for an unknown zone; the caller turns that into a code.
function localParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
  const v = Object.fromEntries(fmt.formatToParts(date).map((p) => [p.type, p.value]));
  return {
    day: `${v.year}-${v.month}-${v.day}`,
    minutes: Number(v.hour) * 60 + Number(v.minute),
  };
}

function toMinutes(hhmm) {
  const m = HH_MM.exec(typeof hhmm === 'string' ? hhmm : '');
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

// Start included, end excluded. start > end wraps past midnight. start === end is empty.
function inWindow(minute, start, end) {
  if (start === end) return false;
  return start < end ? minute >= start && minute < end : minute >= start || minute < end;
}

export function createPushGate() {
  // userId -> Map<localDay, pushesAllowed>
  const sent = new Map();

  function countFor(userId, day) {
    return sent.get(userId)?.get(day) ?? 0;
  }

  function record(userId, day) {
    let days = sent.get(userId);
    if (!days) {
      days = new Map();
      sent.set(userId, days);
    }
    days.set(day, (days.get(day) ?? 0) + 1);
    // Keep memory bounded: drop the oldest local days once there are more than KEEP_DAYS.
    while (days.size > KEEP_DAYS) {
      const oldest = [...days.keys()].sort()[0];
      days.delete(oldest);
    }
  }

  return {
    attempt(user, now) {
      if (!user || typeof user !== 'object') return refuse('invalid_user');
      if (!(now instanceof Date) || Number.isNaN(now.getTime())) return refuse('invalid_time');

      let local;
      try {
        local = localParts(now, user.timeZone);
      } catch {
        return refuse('invalid_time_zone');
      }

      const start = toMinutes(user.quietStart);
      const end = toMinutes(user.quietEnd);
      if (start === null || end === null) return refuse('invalid_quiet_hours');

      const cap = user.dailyCap;
      if (!Number.isInteger(cap) || cap < 0) return refuse('invalid_daily_cap');

      if (inWindow(local.minutes, start, end)) return refuse('quiet_hours');

      if (countFor(user.id, local.day) >= cap) return refuse('daily_cap_reached');

      record(user.id, local.day);
      return { allowed: true, reason: null };
    },
  };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/ours-g2-1/bot.mjs';

const tokyo = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (iso) => new Date(iso);

// Quiet window in Tokyo (UTC+9): 22:00-07:00 local.
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T12:00:00Z')), { allowed: true, reason: null }); // 21:00 local
  assert.equal(g.attempt(tokyo, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours'); // 22:00 local, start included
  assert.equal(g.attempt(tokyo, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(tokyo, at('2026-10-22T14:59:00Z')).reason, 'quiet_hours'); // 23:59 local
  assert.equal(g.attempt(tokyo, at('2026-10-21T22:00:00Z')).reason, 'quiet_hours'); // 07:00 is excluded? no: 07:00 local = 22:00Z prev day
}

// End minute is excluded: 07:00 local is allowed.
{
  const g = createPushGate();
  const r = g.attempt(tokyo, at('2026-10-21T22:00:00Z')); // 2026-10-22 07:00 local
  assert.deepEqual(r, { allowed: true, reason: null });
  assert.equal(g.attempt(tokyo, at('2026-10-21T21:59:00Z')).reason, 'quiet_hours'); // 06:59 local
}

// Daily cap counts the user's local calendar day; refusals spend nothing.
{
  const g = createPushGate();
  const day = { ...tokyo, quietStart: '00:00', quietEnd: '00:00' }; // no quiet window
  assert.equal(g.attempt(day, at('2026-10-22T03:00:00Z')).allowed, true);
  assert.equal(g.attempt(day, at('2026-10-22T04:00:00Z')).allowed, true);
  assert.equal(g.attempt(day, at('2026-10-22T05:00:00Z')).allowed, true);
  assert.equal(g.attempt(day, at('2026-10-22T06:00:00Z')).reason, 'daily_cap_reached');
  // 14:59Z = 23:59 local still Oct 22; 15:00Z = 00:00 local Oct 23 -> new day
  assert.equal(g.attempt(day, at('2026-10-22T14:59:00Z')).reason, 'daily_cap_reached');
  assert.deepEqual(g.attempt(day, at('2026-10-22T15:00:00Z')), { allowed: true, reason: null });
}

// Cap 0 blocks everything; reason is cap, not quiet.
{
  const g = createPushGate();
  assert.equal(g.attempt({ ...tokyo, dailyCap: 0, quietStart: '00:00', quietEnd: '00:00' }, at('2026-10-22T03:00:00Z')).reason, 'daily_cap_reached');
}

// Gates are independent; same user id in two gates has separate history.
{
  const a = createPushGate();
  const b = createPushGate();
  const day = { ...tokyo, dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(a.attempt(day, at('2026-10-22T03:00:00Z')).allowed, true);
  assert.equal(a.attempt(day, at('2026-10-22T03:30:00Z')).reason, 'daily_cap_reached');
  assert.equal(b.attempt(day, at('2026-10-22T03:30:00Z')).allowed, true);
}

// Per-call settings: the same gate uses what each call passes in.
{
  const g = createPushGate();
  const u = { id: 'u_1', timeZone: 'Europe/Berlin', quietStart: '22:00', quietEnd: '07:00', dailyCap: 5 };
  assert.equal(g.attempt(u, at('2026-10-22T21:30:00Z')).reason, 'quiet_hours'); // 23:30 Berlin
  assert.equal(g.attempt({ ...u, quietStart: '00:00', quietEnd: '00:00' }, at('2026-10-22T21:30:00Z')).allowed, true);
}

// DST: New York springs forward 2026-03-08 at 02:00 local.
{
  const g = createPushGate();
  const ny = { id: 'u_ny', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 9 };
  assert.equal(g.attempt(ny, at('2026-03-08T06:59:00Z')).reason, 'quiet_hours'); // 01:59 EST
  assert.equal(g.attempt(ny, at('2026-03-08T07:30:00Z')).reason, 'quiet_hours'); // 03:30 EDT
  assert.deepEqual(g.attempt(ny, at('2026-03-08T11:00:00Z')), { allowed: true, reason: null }); // 07:00 EDT
}

// Held, not guessed.
{
  const g = createPushGate();
  const now = at('2026-10-22T12:00:00Z');
  assert.equal(g.attempt({ ...tokyo, timeZone: 'Mars/Olympus' }, now).reason, 'invalid_time_zone');
  assert.equal(g.attempt({ ...tokyo, timeZone: undefined }, now).reason, 'invalid_time_zone');
  assert.equal(g.attempt({ ...tokyo, quietStart: '25:00' }, now).reason, 'invalid_quiet_hours');
  assert.equal(g.attempt({ ...tokyo, quietEnd: undefined }, now).reason, 'invalid_quiet_hours');
  assert.equal(g.attempt({ ...tokyo, dailyCap: -1 }, now).reason, 'invalid_daily_cap');
  assert.equal(g.attempt({ ...tokyo, dailyCap: 1.5 }, now).reason, 'invalid_daily_cap');
  assert.equal(g.attempt(tokyo, new Date('nope')).reason, 'invalid_time');
  assert.equal(g.attempt(null, now).reason, 'invalid_user');
}

// Window that does not wrap: 13:00-14:00 local.
{
  const g = createPushGate();
  const u = { id: 'u_nw', timeZone: 'UTC', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T12:59:00Z')).allowed, true);
  assert.equal(g.attempt(u, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, at('2026-10-22T14:00:00Z')).allowed, true);
}

console.log('all checks passed');

